<?php
/** Proof — staffing and rates (spec "Proof", 2): Priya staffed as consultant from a date; the same dates again → "already staffed"; her resolved rate 180 from the card; a role rate 200 overrides; her override 210 wins; ending; a manager who is not the engagement's cannot staff it. */
require __DIR__ . '/lib.php';
$marco = as_member(27); $priya = as_member(26); $bea = as_member(28);
[$acme, $card] = fixture_client();
[$c, $b] = act($marco, '/engagements/save.php', ['client' => $acme, 'name' => 'SMOKE Staffing eng', 'kind' => 'time_and_materials', 'start_date' => '2026-01-05', 'start_now' => 'yes']);
$eng = (int) $b['record_id'];
$num = (string) one('SELECT number FROM engagements WHERE id = :e', ['e' => $eng]);

echo "1. Staffing\n";
$since = last_activity_id();
[$c, $b] = act($marco, '/engagements/staffing/save.php', ['engagement' => $eng, 'member' => 26, 'role' => role('consultant'), 'valid_from' => '2026-02-01', 'note' => 'SMOKE half time']);
$st = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $st > 0 && str_ends_with((string) $b['location'], '/engagements/' . $eng . '/staffing?notice=staffed#staffing-row-' . $st) && str_starts_with((string) $b['did'], 'Staffed SMOKE Priya as Consultant'), "engagement_member_save: record_id $st, lands on the staffing tab");
$log = activity('engagement.staff', $since);
ok(count($log) === 1 && (int) $log[0]['engagement_id'] === $eng && json_decode((string) $log[0]['after'], true) == ['member_id' => 26, 'consulting_role_id' => role('consultant'), 'valid_from' => '2026-02-01', 'valid_to' => null, 'has_override' => false], 'engagement.staff logged with the member, role, dates and has_override (never a rate)');
[$c, $b] = act($marco, '/engagements/staffing/save.php', ['engagement' => $eng, 'member' => 26, 'role' => role('analyst'), 'valid_from' => '2026-03-01']);
ok($c === 422 && msg($b) === 'SMOKE Priya is already staffed on ' . $num . ' over those dates.', 'the same person over overlapping dates: 422 "SMOKE Priya is already staffed on ' . $num . ' over those dates."' . ($c === 422 && msg($b) === 'SMOKE Priya is already staffed on ' . $num . ' over those dates.' ? '' : " (got $c " . msg($b) . ')'));
[$c, $b] = act($marco, '/engagements/staffing/save.php', ['engagement' => $eng, 'member' => 26, 'role' => role('analyst'), 'valid_from' => '2026-01-10', 'valid_to' => '2026-01-20']);
ok($c === 200, 'an earlier closed range for her (another role) is allowed');
[$c, $b] = act($marco, '/engagements/staffing/save.php', ['engagement' => $eng, 'member' => 30, 'role' => role('analyst'), 'valid_from' => '2026-04-01', 'valid_to' => '2026-03-01']);
ok($c === 422 && isset(fields($b)['valid_to']), 'an end before the start: 422' . ($c === 422 && isset(fields($b)['valid_to']) ? '' : " (got $c " . json_encode($b) . ')'));
[$c, $b] = act($marco, '/engagements/staffing/save.php', ['engagement' => $eng, 'member' => 999, 'role' => role('analyst')]);
ok($c === 422 && isset(fields($b)['member']), 'a member the mirror does not admit: 422');
[$c, $b] = act($marco, '/engagements/staffing/save.php', ['engagement' => $eng, 'member' => 40, 'role' => role('analyst'), 'valid_from' => '2026-02-01']);
ok($c === 200, 'an agent (the Clerk) may be staffed');
[$c, $d] = screen($marco, '/engagements/' . $eng . '/staffing');
ok($c === 200 && $d['tab'] === 'staffing' && count($d['engagement']['staffing']) === 4 && $d['engagement']['staffing'][0]['is_current'] === true, 'the staffing tab lists four rows (Marco, Priya twice, the Clerk), current first');

echo "2. The rate resolution\n";
$r = q("SELECT * FROM ct_resolve_rate(:e, 26, '2026-02-15')", ['e' => $eng])[0];
ok($r['bill_rate'] === '180.00' && $r['rate_source'] === 'rate_card' && (int) $r['consulting_role_id'] === role('consultant'), 'Priya resolves to 180 from the card (Consultant)');
$r = q("SELECT * FROM ct_resolve_rate(:e, 26, '2026-01-15')", ['e' => $eng])[0];
ok($r['bill_rate'] === '125.00' && (int) $r['consulting_role_id'] === role('analyst'), 'in January she was an Analyst: 125');
$since = last_activity_id();
[$c, $b] = act($marco, '/engagements/rates/save.php', ['engagement' => $eng, 'role' => role('consultant'), 'bill_rate' => '200']);
ok($c === 200 && (string) q("SELECT bill_rate FROM ct_resolve_rate(:e, 26, '2026-02-15')", ['e' => $eng])[0]['bill_rate'] === '200.00' && q("SELECT rate_source FROM ct_resolve_rate(:e, 26, '2026-02-15')", ['e' => $eng])[0]['rate_source'] === 'engagement_role', 'a role rate of 200 on the engagement overrides the card');
$log = activity('engagement.role_rate', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['before'], true) === ['role_id' => role('consultant'), 'bill_rate' => null] && json_decode((string) $log[0]['after'], true) === ['role_id' => role('consultant'), 'bill_rate' => '200.00'], 'engagement.role_rate logs the role and before/after');
[$c, $b] = act($marco, '/engagements/staffing/save.php', ['staffing' => $st, 'bill_rate_override' => '210']);
ok($c === 200 && (string) q("SELECT bill_rate FROM ct_resolve_rate(:e, 26, '2026-02-15')", ['e' => $eng])[0]['bill_rate'] === '210.00' && q("SELECT rate_source FROM ct_resolve_rate(:e, 26, '2026-02-15')", ['e' => $eng])[0]['rate_source'] === 'member_override', 'her own override of 210 wins');
$staffLog = activity('engagement.staff', 0); $lastStaff = end($staffLog);
ok(str_contains((string) $lastStaff['after'], '"has_override": true') && !str_contains((string) $lastStaff['after'], '210'), 'the staffing log says has_override, never the figure');
[$c, $d] = screen($marco, '/engagements/' . $eng . '/rates');
$priyaRow = array_values(array_filter($d['engagement']['role_rates']['people'], fn ($p) => $p['member_id'] === 26))[0] ?? null;
$consultant = array_values(array_filter($d['engagement']['role_rates']['roles'], fn ($r) => $r['consulting_role_id'] === role('consultant')))[0];
ok($c === 200 && $priyaRow['bill_rate'] === '210.00' && $priyaRow['rate_source'] === 'member_override' && $consultant['card_rate'] === '180.00' && $consultant['engagement_rate'] === '200.00' && $d['engagement']['role_rates']['card_name'] === 'SMOKE Standard', 'the rates tab shows the card\'s 180, the engagement\'s 200, and Priya\'s resolution (210, her override)');
[$c, $b] = act($marco, '/engagements/rates/save.php', ['engagement' => $eng, 'role' => role('consultant'), 'bill_rate' => '']);
ok($c === 200 && (int) one('SELECT count(*) FROM engagement_role_rates WHERE engagement_id = :e', ['e' => $eng]) === 0, 'an empty rate removes the override');
ok(page($priya, '/engagements/' . $eng . '/rates')['code'] === 403, 'Priya (no rates.view) gets 403 on the rates tab');
[$c, $d] = screen($priya, '/engagements/' . $eng . '/staffing');
ok($c === 200 && $d['engagement']['staffing'][0]['bill_rate_override'] === null && $d['engagement']['rate_card_id'] === null, 'on the staffing tab she sees no override and no card');

echo "3. Ending a staffing; who may staff\n";
$since = last_activity_id();
[$c, $b] = act($marco, '/engagements/staffing/end.php', ['staffing' => $st, 'valid_to' => '2026-06-30']);
ok($c === 200 && (string) one('SELECT valid_to FROM engagement_members WHERE id = :s', ['s' => $st]) === '2026-06-30' && count(activity('engagement.unstaff', $since)) === 1, 'ended on Jun 30, logged');
ok(one("SELECT ct_can_log_on(:e, 26, '2026-06-29')", ['e' => $eng]) && !one("SELECT ct_can_log_on(:e, 26, '2026-06-30')", ['e' => $eng]), 'ct_can_log_on(): yes on Jun 29, no from Jun 30 (slice 3 refuses the entry)');
[$c, $b] = act($marco, '/engagements/staffing/end.php', ['staffing' => $st, 'valid_to' => '2026-01-01']);
ok($c === 422 && str_contains(msg($b), 'already ended'), 'ending an ended staffing again: 422 "That staffing already ended on …"');
[$c, $b] = act($marco, '/engagements/staffing/save.php', ['engagement' => $eng, 'member' => 26, 'role' => role('senior_consultant'), 'valid_from' => '2026-07-01']);
ok($c === 200, 're-staffed later in another role: a new row');
[$c, $b] = act($bea, '/engagements/save.php', ['client' => $acme, 'name' => 'SMOKE Beas eng', 'kind' => 'time_and_materials', 'manager' => 28]);
$other = (int) $b['record_id'];
[$c, $b] = act($marco, '/engagements/staffing/save.php', ['engagement' => $other, 'member' => 26, 'role' => role('consultant')]);
ok($c === 404, 'a Manager who is not the engagement\'s manager (nor its practice\'s admin) cannot staff it: 404 — it is not even visible to him');
[$c, $b] = act($marco, '/engagements/hold.php', ['engagement' => $other]);
ok($c === 404, 'nor move it: 404');
ok(page($marco, '/engagements/' . $other)['code'] === 404, 'nor see it (not staffed, not his practice)');
[$c, $b] = act($bea, '/engagements/staffing/save.php', ['engagement' => $other, 'member' => 27, 'role' => role('consultant')]);
ok($c === 200 && page($marco, '/engagements/' . $other)['code'] === 200 && json_decode(page($marco, '/engagements/' . $other, ['headers' => JSONH])['body'], true)['data']['engagement']['i_manage'] === false, 'once Bea staffs him he sees it, with i_manage false');
finish();
